def reactive_agent(state):
    if state["attempts"] >= 1:
        return {"action": "finish" if state["last_passed"] else "stop"}
    issue = state["issue"]
    prompt = (
        "Repair this TypeScript source file. Return only the complete replacement code. "
        "Do not alter tests or public interfaces.\n"
        "Issue: " + issue["report"] + "\n"
        "File: " + issue["file"] + "\n"
        "Source:\n" + state["source"] + "\n"
        "Compiler and test feedback:\n" + state["feedback"]
    )
    return {"action": "generate", "prompt": prompt}

def intelligent_agent(state):
    if state["last_passed"]:
        return {"action": "finish"}
    if state["attempts"] >= state["max_attempts"]:
        return {"action": "stop"}
    issue = state["issue"]
    earlier = "\n".join(
        "Attempt " + str(i + 1) + ": " + str(x["feedback"])
        for i, x in enumerate(state["history"])
    )
    prompt = (
        "You are repairing a TypeScript application. "
        "Return ONLY the complete corrected TypeScript file. "
        "Keep public interfaces and do not modify tests.\n"
        "Issue: " + issue["report"] + "\n"
        "File: " + issue["file"] + "\n"
        "Current source:\n" + state["source"] + "\n"
        "Latest compiler and test feedback:\n" + state["feedback"] + "\n"
        "Earlier attempts:\n" + earlier
    )
    return {"action": "generate", "prompt": prompt}

def summarize_runs(rows):
    summary = {}
    for name in ("reactive", "intelligent"):
        subset = [r for r in rows if r["strategy"] == name]
        if not subset:
            continue
        n = len(subset)
        summary[name] = {
            "runs": n,
            "success_rate": sum(bool(r["success"]) for r in subset) / n,
            "mean_elapsed_ms": sum(r["elapsed_ms"] for r in subset) / n,
            "mean_tool_bytes": sum(r["tool_bytes"] for r in subset) / n,
        }
    return summary
